/** Resolve article slugs to link cards, silently dropping any that no longer exist. */
export function resolveBlogCards(slugs: string[]) {
  return slugs.flatMap((slug) => {
    const meta = blogCardIndex[slug];
    return meta ? [{ slug, title: meta.title, img: meta.img, cat: meta.cat }] : [];
  });
}
